package app.kivo.store;
import android.app.*;import android.content.*;import android.os.*;import android.icu.util.ULocale;import android.view.translation.*;import org.json.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
/** In-app online translation after explicit consent, with cache and optional device translation. */
final class DescriptionTranslator {
 final MainActivity host;final ExecutorService jobs=Executors.newSingleThreadExecutor();
 DescriptionTranslator(MainActivity h){host=h;}
 void open(String raw){final String repo;try{repo=MainActivity.repo(raw);}catch(Exception e){return;}JSONObject app=host.catalog.get(repo);if(app==null)app=host.sourceEntry(repo);if(app==null){host.status("Abre la ficha de la app e inténtalo de nuevo.");return;}String longText=app.optString("longDescription"),text=longText.isEmpty()?app.optString("description"):longText;if(text.trim().isEmpty()){host.status("Esta ficha no tiene descripción para traducir.");return;}final String original=TranslationText.limit(text,12000);android.widget.Spinner language=new android.widget.Spinner(host);language.setAdapter(new android.widget.ArrayAdapter<String>(host,android.R.layout.simple_spinner_dropdown_item,new String[]{"Original en inglés","Original en francés","Original en portugués","Original en alemán","Original en ruso","Original en italiano","Original en chino","Original en japonés","Original en coreano"}));new AlertDialog.Builder(host).setTitle("Traducir al español").setMessage("La traducción se mostrará aquí. Para traducir con conexión se envía únicamente esta descripción pública a MyMemory, no tu cuenta ni tus apps instaladas. El servicio gratuito tiene un límite diario. En textos largos se traduce un máximo de 3,000 caracteres. Elige el idioma original:").setView(language).setPositiveButton("Traducir aquí",(d,w)->network(repo,original,new String[]{"en","fr","pt","de","ru","it","zh","ja","ko"}[language.getSelectedItemPosition()])).setNeutralButton("Sin conexión",(d,w)->{if(Build.VERSION.SDK_INT<31){state(repo,false,"","Este Android no ofrece traducción local. Usa Traducir aquí con conexión.");return;}translate(repo,original,new String[]{"en","fr","pt","de","ru","it","zh","ja","ko"}[language.getSelectedItemPosition()]);}).setNegativeButton("Cancelar",null).show();}
 void network(String repo,String original,String source){state(repo,true,"","");jobs.execute(()->{StringBuilder translated=new StringBuilder();try{String input=TranslationText.limit(original,3000);String note=input.length()<original.length()?"Traducción de los primeros 3,000 caracteres. Puedes volver al original completo.":"";File cacheDir=new File(host.getCacheDir(),"translations");cacheDir.mkdirs();File cache=new File(cacheDir,MainActivity.hex(java.security.MessageDigest.getInstance("SHA-256").digest((source+"|es|"+input).getBytes("UTF-8")))+".json");if(cache.isFile())try(InputStream in=new FileInputStream(cache)){JSONObject saved=new JSONObject(MainActivity.read(in,128000));state(repo,false,saved.getString("text"),"","MyMemory",note);return;}catch(Exception ignored){cache.delete();}
  for(String chunk:TranslationText.chunks(input,480)){if(Thread.currentThread().isInterrupted())return;String url="https://api.mymemory.translated.net/get?q="+URLEncoder.encode(chunk,"UTF-8")+"&langpair="+URLEncoder.encode(source+"|es","UTF-8");HttpURLConnection connection=(HttpURLConnection)new URL(url).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(8000);connection.setReadTimeout(12000);connection.setRequestProperty("User-Agent","Kivo-Store/0.9.6");connection.setRequestProperty("Accept","application/json");try{int code=connection.getResponseCode();if(code==429)throw new IOException("Se alcanzó el límite gratuito de traducción. Inténtalo más tarde.");if(code!=200)throw new IOException("El traductor no respondió. Revisa la conexión y vuelve a intentarlo.");JSONObject response;try(InputStream in=connection.getInputStream()){response=new JSONObject(MainActivity.read(in,256000));}String value=TranslationText.response(response);if(translated.length()>0)translated.append(' ');translated.append(android.text.Html.fromHtml(value,android.text.Html.FROM_HTML_MODE_LEGACY).toString());}finally{connection.disconnect();}}
  try(OutputStream out=new FileOutputStream(cache)){out.write(new JSONObject().put("text",translated.toString()).toString().getBytes("UTF-8"));}catch(Exception ignored){}File[] files=cacheDir.listFiles();if(files!=null&&files.length>100){Arrays.sort(files,Comparator.comparingLong(File::lastModified));for(int i=0;i<files.length-100;i++)files[i].delete();}state(repo,false,translated.toString(),"","MyMemory",note);
 }catch(Exception e){state(repo,false,translated.toString(),e instanceof IOException&&e.getMessage()!=null?e.getMessage():"No se pudo traducir. Revisa la conexión e inténtalo de nuevo.","MyMemory",translated.length()>0?"Traducción parcial; el original completo sigue disponible.":"");}});}
 void state(String repo,boolean busy,String text,String error){state(repo,busy,text,error,"del dispositivo","");}
 void state(String repo,boolean busy,String text,String error,String provider,String note){try{host.send("translation",new JSONObject().put("repo",repo).put("busy",busy).put("text",text).put("error",error).put("provider",provider).put("note",note));}catch(Exception ignored){}}
 void translate(String repo,String text,String source){state(repo,true,"","");jobs.execute(()->{try{Api31.start(this,repo,text,source);}catch(Throwable e){state(repo,false,"","No hay traducción local disponible. Elige Traducir aquí con conexión.");}});}
 static final class Api31 {
  static void start(DescriptionTranslator owner,String repo,String text,String source){MainActivity host=owner.host;TranslationManager manager=host.getSystemService(TranslationManager.class);if(manager==null)throw new IllegalStateException();AtomicBoolean done=new AtomicBoolean();Translator[] active=new Translator[1];CancellationSignal cancel=new CancellationSignal();Handler handler=new Handler(Looper.getMainLooper());Runnable timeout=()->{if(done.compareAndSet(false,true)){cancel.cancel();if(active[0]!=null)active[0].destroy();owner.state(repo,false,"","El traductor del dispositivo no respondió. Vuelve a Traducir al español y elige Traducir aquí con conexión.");}};handler.postDelayed(timeout,20000);
   TranslationContext context=new TranslationContext.Builder(new TranslationSpec(new ULocale(source),TranslationSpec.DATA_FORMAT_TEXT),new TranslationSpec(new ULocale("es"),TranslationSpec.DATA_FORMAT_TEXT)).build();manager.createOnDeviceTranslator(context,host.getMainExecutor(),translator->{if(done.get()){if(translator!=null)translator.destroy();return;}if(translator==null){done.set(true);handler.removeCallbacks(timeout);owner.state(repo,false,"","Este teléfono no ofrece traducción del sistema para estos idiomas.");return;}active[0]=translator;try{TranslationRequest request=new TranslationRequest.Builder().setTranslationRequestValues(Collections.singletonList(TranslationRequestValue.forText(text))).build();translator.translate(request,cancel,host.getMainExecutor(),response->{if(!done.compareAndSet(false,true))return;handler.removeCallbacks(timeout);try{TranslationResponseValue value=response.getTranslationResponseValues().get(0);if(response.getTranslationStatus()!=TranslationResponse.TRANSLATION_STATUS_SUCCESS||value==null||value.getText()==null||value.getText().length()==0)throw new IllegalStateException();owner.state(repo,false,value.getText().toString(),"");}catch(Exception e){owner.state(repo,false,"","No se pudo traducir. El original sigue disponible.");}finally{translator.destroy();}});}catch(Exception e){if(done.compareAndSet(false,true)){handler.removeCallbacks(timeout);translator.destroy();owner.state(repo,false,"","No se pudo iniciar el traductor del dispositivo.");}}});
  }
 }
 void close(){jobs.shutdownNow();}
}
